```python
# Promisify: convert callback-based function to a promise-based function
def promisify(fn):
    # Returns a function that accepts all the same args except callback
    def promised_fn(*args):
        import asyncio

        async def _promise():
            loop = asyncio.get_event_loop()
            future = loop.create_future()

            def callback(result=None, error=None):
                # Only the first call settles the future
                if future.done():
                    return
                # If error, reject the future
                if error is not None:
                    future.set_exception(
                        error if isinstance(error, BaseException) else Exception(error)
                    )
                else:
                    future.set_result(result)
            try:
                # Call original function: callback goes first, then args
                fn(callback, *args)
            except Exception as exc:
                if not future.done():
                    future.set_exception(exc)
            return await future
        return _promise()
    return promised_fn

# Usage:
